test_suite:
test('Portal renders children into document.body by default', () => {
  const { Portal } = renderHook(() => usePortal()).result.current;
  render(<Portal><div data-testid="portal-child">Hello</div></Portal>);
  expect(document.body.querySelector('[data-testid="portal-child"]')).toBeTruthy();
});

test('Portal renders into provided container', () => {
  const container = document.createElement('div');
  document.body.appendChild(container);
  const { Portal } = renderHook(() => usePortal(container)).result.current;
  render(<Portal><span data-testid="child">X</span></Portal>);
  expect(container.querySelector('[data-testid="child"]')).toBeTruthy();
  document.body.removeChild(container);
});

test('Portal is a React component (function)', () => {
  const { result } = renderHook(() => usePortal());
  expect(typeof result.current.Portal).toBe('function');
});

test('Portal renders multiple children', () => {
  const { Portal } = renderHook(() => usePortal()).result.current;
  render(<Portal><div id="a" /><div id="b" /></Portal>);
  expect(document.body.querySelector('#a')).toBeTruthy();
  expect(document.body.querySelector('#b')).toBeTruthy();
});

// __hidden__
test('children do not appear in parent component DOM tree', () => {
  const { Portal } = renderHook(() => usePortal()).result.current;
  const { container } = render(<div id="parent"><Portal><div id="teleported" /></Portal></div>);
  expect(container.querySelector('#teleported')).toBeNull();
});

solution:
import { useMemo } from 'react';
import { createPortal } from 'react-dom';
import type { ReactNode } from 'react';

export function usePortal(container?: Element) {
  const Portal = useMemo(() => {
    return function Portal({ children }: { children: ReactNode }) {
      return createPortal(children, container ?? document.body);
    };
  }, [container]);

  return { Portal };
}
